def validate_api_url(api_url: str) -> bool:
    # Basic validation to check if the URL starts with http or https
    return api_url.startswith('http://') or api_url.startswith('https://')

# Example usage
print(validate_api_url('https://example.com/api/user'))  # Expected: True
print(validate_api_url('ftp://example.com/api/user'))    # Expected: False

