import re

def test_user_id_validation():
    valid_user_ids = ['aBc123', 'user_1', 'user-2']
    invalid_user_ids = ['', 'user@123', 'user!name', 'user name']

    for user_id in valid_user_ids:
        assert re.match(r'^[\w-]+$', user_id), f"Valid user_id '{user_id}' failed validation"

    for user_id in invalid_user_ids:
        assert not re.match(r'^[\w-]+$', user_id), f"Invalid user_id '{user_id}' passed validation"

